let rec token lexbuf =
  lexbuf.Lexing.lex_mem <- Array.make 9 (-1);(* L=1 [2] <- p ;  *)
  lexbuf.Lexing.lex_mem.(2) <- lexbuf.Lexing.lex_curr_pos ;
 __ocaml_lex_token_rec lexbuf 0
and __ocaml_lex_token_rec lexbuf __ocaml_lex_state =
  match Lexing.new_engine __ocaml_lex_tables __ocaml_lex_state lexbuf with
      | 0 ->
let
             bs
= Lexing.sub_lexeme_char lexbuf lexbuf.Lexing.lex_start_pos in
                         (
      if not !escaped_newlines then error lexbuf (Illegal_character bs);
      update_loc lexbuf None 1 false 0;
      token lexbuf )

  | 1 ->
      ( update_loc lexbuf None 1 false 0;
        EOL )

  | 2 ->
      ( token lexbuf )

  | 3 ->
      ( UNDERSCORE )

  | 4 ->
      ( TILDE )

  | 5 ->
      ( error lexbuf
          (Reserved_sequence (".~", Some "is reserved for use in MetaOCaml")) )

  | 6 ->
let
                                   name
= Lexing.sub_lexeme lexbuf (lexbuf.Lexing.lex_start_pos + 1) (lexbuf.Lexing.lex_curr_pos + -1) in
      ( check_label_name lexbuf name;
        LABEL name )

  | 7 ->
let
                              escape
= Lexing.sub_lexeme lexbuf (lexbuf.Lexing.lex_start_pos + 1) lexbuf.Lexing.lex_mem.(0)
and
                                                    raw_name
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_mem.(0) (lexbuf.Lexing.lex_curr_pos + -1) in
      ( let name = ident_for_extended lexbuf raw_name in
        check_label_name ~raw_escape:(escape<>"") lexbuf name;
        LABEL name )

  | 8 ->
      ( QUESTION )

  | 9 ->
let
                                  name
= Lexing.sub_lexeme lexbuf (lexbuf.Lexing.lex_start_pos + 1) (lexbuf.Lexing.lex_curr_pos + -1) in
      ( check_label_name lexbuf name;
        OPTLABEL name )

  | 10 ->
let
                              escape
= Lexing.sub_lexeme lexbuf (lexbuf.Lexing.lex_start_pos + 1) lexbuf.Lexing.lex_mem.(0)
and
                                                    raw_name
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_mem.(0) (lexbuf.Lexing.lex_curr_pos + -1) in
      ( let name = ident_for_extended lexbuf raw_name in
        check_label_name ~raw_escape:(escape<>"") lexbuf name;
        OPTLABEL name
      )

  | 11 ->
let
                             name
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_curr_pos in
      ( find_keyword lexbuf name )

  | 12 ->
let
                             name
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_curr_pos in
      ( UIDENT name )

  | 13 ->
let
                          escape
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_mem.(0)
and
                                                raw_name
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_mem.(0) lexbuf.Lexing.lex_curr_pos in
      ( let name = ident_for_extended lexbuf raw_name in
        if Utf8_lexeme.is_capitalized name then begin
            if escape="" then UIDENT name
            else
              (* we don't have capitalized keywords, and thus no needs for
                 capitalized raw identifiers. *)
              error lexbuf (Capitalized_raw_identifier name)
        end else
          LIDENT name
      )

  | 14 ->
let
                   lit
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_curr_pos in
                       ( INT (lit, None) )

  | 15 ->
let
                    lit
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos (lexbuf.Lexing.lex_curr_pos + -1)
and
                                              modif
= Lexing.sub_lexeme_char lexbuf (lexbuf.Lexing.lex_curr_pos + -1) in
      ( INT (lit, Some modif) )

  | 16 ->
let
                                         lit
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_curr_pos in
      ( FLOAT (lit, None) )

  | 17 ->
let
                                          lit
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos (lexbuf.Lexing.lex_curr_pos + -1)
and
                                                                    modif
= Lexing.sub_lexeme_char lexbuf (lexbuf.Lexing.lex_curr_pos + -1) in
      ( FLOAT (lit, Some modif) )

  | 18 ->
let
                                                                    invalid
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_curr_pos in
      ( error lexbuf (Invalid_literal invalid) )

  | 19 ->
      ( let s, loc = wrap_string_lexer string lexbuf in
        STRING (s, loc, None) )

  | 20 ->
let
                      raw_name
= Lexing.sub_lexeme lexbuf (lexbuf.Lexing.lex_start_pos + 1) (lexbuf.Lexing.lex_curr_pos + -1) in
      ( let delim = validate_delim lexbuf raw_name in
        let s, loc = wrap_string_lexer (quoted_string delim) lexbuf in
        STRING (s, loc, Some delim)
       )

  | 21 ->
let
                          raw_id
= Lexing.sub_lexeme lexbuf (lexbuf.Lexing.lex_start_pos + 2) (lexbuf.Lexing.lex_curr_pos + -1) in
      ( let orig_loc = Location.curr lexbuf in
        let id = validate_ext lexbuf raw_id in
        let s, loc = wrap_string_lexer (quoted_string "") lexbuf in
        let idloc = compute_quoted_string_idloc orig_loc 2 id in
        QUOTED_STRING_EXPR (id, idloc, s, loc, Some "") )

  | 22 ->
let
                          raw_id
= Lexing.sub_lexeme lexbuf (lexbuf.Lexing.lex_start_pos + 2) lexbuf.Lexing.lex_mem.(0)
and
                                                       raw_delim
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_mem.(1) (lexbuf.Lexing.lex_curr_pos + -1) in
      ( let orig_loc = Location.curr lexbuf in
        let id = validate_ext lexbuf raw_id in
        let delim = validate_delim lexbuf raw_delim in
        let s, loc = wrap_string_lexer (quoted_string delim) lexbuf in
        let idloc = compute_quoted_string_idloc orig_loc 2 id in
        QUOTED_STRING_EXPR (id, idloc, s, loc, Some delim) )

  | 23 ->
let
                           raw_id
= Lexing.sub_lexeme lexbuf (lexbuf.Lexing.lex_start_pos + 3) (lexbuf.Lexing.lex_curr_pos + -1) in
      ( let orig_loc = Location.curr lexbuf in
        let id = validate_ext lexbuf raw_id in
        let s, loc = wrap_string_lexer (quoted_string "") lexbuf in
        let idloc = compute_quoted_string_idloc orig_loc 3 id in
        QUOTED_STRING_ITEM (id, idloc, s, loc, Some "") )

  | 24 ->
let
                           raw_id
= Lexing.sub_lexeme lexbuf (lexbuf.Lexing.lex_start_pos + 3) lexbuf.Lexing.lex_mem.(0)
and
                                                        raw_delim
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_mem.(1) (lexbuf.Lexing.lex_curr_pos + -1) in
      ( let orig_loc = Location.curr lexbuf in
        let id = validate_ext lexbuf raw_id in
        let delim = validate_delim lexbuf raw_delim in
        let s, loc = wrap_string_lexer (quoted_string delim) lexbuf in
        let idloc = compute_quoted_string_idloc orig_loc 3 id in
        QUOTED_STRING_ITEM (id, idloc, s, loc, Some delim) )

  | 25 ->
      ( update_loc lexbuf None 1 false 1;
        (* newline is ('\013'* '\010') *)
        CHAR '\n' )

  | 26 ->
let
                                         c
= Lexing.sub_lexeme_char lexbuf (lexbuf.Lexing.lex_start_pos + 1) in
      ( CHAR c )

  | 27 ->
let
                                                    c
= Lexing.sub_lexeme_char lexbuf (lexbuf.Lexing.lex_start_pos + 2) in
      ( CHAR (char_for_backslash c) )

  | 28 ->
      ( CHAR(char_for_decimal_code lexbuf 2) )

  | 29 ->
      ( CHAR(char_for_octal_code lexbuf 3) )

  | 30 ->
      ( CHAR(char_for_hexadecimal_code lexbuf 3) )

  | 31 ->
let
                          esc
= Lexing.sub_lexeme lexbuf (lexbuf.Lexing.lex_start_pos + 1) (lexbuf.Lexing.lex_start_pos + 3) in
      ( error lexbuf (Illegal_escape (esc, None)) )

  | 32 ->
      ( error lexbuf Empty_character_literal )

  | 33 ->
      ( let s, loc = wrap_comment_lexer comment lexbuf in
        COMMENT (s, loc) )

  | 34 ->
      ( let s, loc = wrap_comment_lexer comment lexbuf in
        if !handle_docstrings then
          DOCSTRING (Docstrings.docstring s loc)
        else
          COMMENT ("*" ^ s, loc)
      )

  | 35 ->
let
                     stars
= Lexing.sub_lexeme lexbuf (lexbuf.Lexing.lex_start_pos + 3) lexbuf.Lexing.lex_curr_pos in
      ( let s, loc =
          wrap_comment_lexer
            (fun lexbuf ->
               store_string ("*" ^ stars);
               comment lexbuf)
            lexbuf
        in
        COMMENT (s, loc) )

  | 36 ->
      ( if !print_warnings then
          Location.prerr_warning (Location.curr lexbuf) Warnings.Comment_start;
        let s, loc = wrap_comment_lexer comment lexbuf in
        COMMENT (s, loc) )

  | 37 ->
let
                    stars
= Lexing.sub_lexeme lexbuf (lexbuf.Lexing.lex_start_pos + 2) (lexbuf.Lexing.lex_curr_pos + -2) in
      ( if !handle_docstrings && stars="" then
         (* (**) is an empty docstring *)
          DOCSTRING(Docstrings.docstring "" (Location.curr lexbuf))
        else
          COMMENT (stars, Location.curr lexbuf) )

  | 38 ->
      ( let loc = Location.curr lexbuf in
        Location.prerr_warning loc Warnings.Comment_not_end;
        lexbuf.Lexing.lex_curr_pos <- lexbuf.Lexing.lex_curr_pos - 1;
        let curpos = lexbuf.lex_curr_p in
        lexbuf.lex_curr_p <- { curpos with pos_cnum = curpos.pos_cnum - 1 };
        STAR
      )

  | 39 ->
      ( let at_beginning_of_line pos = (pos.pos_cnum = pos.pos_bol) in
        if not (at_beginning_of_line lexbuf.lex_start_p)
        then HASH
        else try directive lexbuf with Failure _ -> HASH
      )

  | 40 ->
         ( AMPERSAND )

  | 41 ->
         ( AMPERAMPER )

  | 42 ->
         ( BACKQUOTE )

  | 43 ->
         ( QUOTE )

  | 44 ->
         ( LPAREN )

  | 45 ->
         ( RPAREN )

  | 46 ->
         ( STAR )

  | 47 ->
         ( COMMA )

  | 48 ->
         ( MINUSGREATER )

  | 49 ->
         ( DOT )

  | 50 ->
         ( DOTDOT )

  | 51 ->
let
                                      op
= Lexing.sub_lexeme lexbuf (lexbuf.Lexing.lex_start_pos + 1) lexbuf.Lexing.lex_curr_pos in
                                          ( DOTOP op )

  | 52 ->
         ( COLON )

  | 53 ->
         ( COLONCOLON )

  | 54 ->
         ( COLONEQUAL )

  | 55 ->
         ( COLONGREATER )

  | 56 ->
         ( SEMI )

  | 57 ->
         ( SEMISEMI )

  | 58 ->
         ( LESS )

  | 59 ->
         ( LESSMINUS )

  | 60 ->
         ( EQUAL )

  | 61 ->
         ( LBRACKET )

  | 62 ->
         ( LBRACKETBAR )

  | 63 ->
         ( LBRACKETLESS )

  | 64 ->
         ( LBRACKETGREATER )

  | 65 ->
         ( RBRACKET )

  | 66 ->
         ( LBRACE )

  | 67 ->
         ( LBRACELESS )

  | 68 ->
         ( BAR )

  | 69 ->
         ( BARBAR )

  | 70 ->
         ( BARRBRACKET )

  | 71 ->
         ( GREATER )

  | 72 ->
         ( GREATERRBRACKET )

  | 73 ->
         ( RBRACE )

  | 74 ->
         ( GREATERRBRACE )

  | 75 ->
         ( LBRACKETAT )

  | 76 ->
           ( LBRACKETATAT )

  | 77 ->
           ( LBRACKETATATAT )

  | 78 ->
           ( LBRACKETPERCENT )

  | 79 ->
           ( LBRACKETPERCENTPERCENT )

  | 80 ->
         ( BANG )

  | 81 ->
         ( INFIXOP0 "!=" )

  | 82 ->
         ( PLUS )

  | 83 ->
         ( PLUSDOT )

  | 84 ->
         ( PLUSEQ )

  | 85 ->
         ( MINUS )

  | 86 ->
         ( MINUSDOT )

  | 87 ->
let
                                op
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_curr_pos in
            ( PREFIXOP op )

  | 88 ->
let
                                      op
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_curr_pos in
            ( PREFIXOP op )

  | 89 ->
let
                                              op
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_curr_pos in
            ( INFIXOP0 op )

  | 90 ->
let
                              op
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_curr_pos in
            ( INFIXOP1 op )

  | 91 ->
let
                              op
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_curr_pos in
            ( INFIXOP2 op )

  | 92 ->
let
                         op
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_curr_pos in
            ( INFIXOP4 op )

  | 93 ->
            ( PERCENT )

  | 94 ->
let
                                  op
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_curr_pos in
            ( INFIXOP3 op )

  | 95 ->
let
                                op
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_curr_pos in
            ( HASHOP op )

  | 96 ->
let
                                       op
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_curr_pos in
            ( LETOP op )

  | 97 ->
let
                                       op
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_curr_pos in
            ( ANDOP op )

  | 98 ->
        ( EOF )

  | 99 ->
let
          illegal_char
= Lexing.sub_lexeme_char lexbuf lexbuf.Lexing.lex_start_pos in
      ( error lexbuf (Illegal_character illegal_char) )

  | __ocaml_lex_state -> lexbuf.Lexing.refill_buff lexbuf;
      __ocaml_lex_token_rec lexbuf __ocaml_lex_state

and directive lexbuf =
  lexbuf.Lexing.lex_mem <- Array.make 8 (-1);(* L=1 [4] <- p ;  *)
  lexbuf.Lexing.lex_mem.(4) <- lexbuf.Lexing.lex_curr_pos ;
 __ocaml_lex_directive_rec lexbuf 180
and __ocaml_lex_directive_rec lexbuf __ocaml_lex_state =
  match Lexing.new_engine __ocaml_lex_tables __ocaml_lex_state lexbuf with
      | 0 ->
let
                                num
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_mem.(0) lexbuf.Lexing.lex_mem.(1)
and
                                            name
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_mem.(2) lexbuf.Lexing.lex_mem.(3)
and
                                                           directive
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos (lexbuf.Lexing.lex_mem.(3) + 1) in
      (
        match int_of_string num with
        | exception _ ->
            (* PR#7165 *)
            let explanation = "line number out of range" in
            error lexbuf (Invalid_directive ("#" ^ directive, Some explanation))
        | line_num ->
           (* Documentation says that the line number should be
              positive, but we have never guarded against this and it
              might have useful hackish uses. *)
            update_loc lexbuf (Some name) (line_num - 1) true 0;
            token lexbuf
      )

  | __ocaml_lex_state -> lexbuf.Lexing.refill_buff lexbuf;
      __ocaml_lex_directive_rec lexbuf __ocaml_lex_state

and comment lexbuf =
  lexbuf.Lexing.lex_mem <- Array.make 3 (-1); __ocaml_lex_comment_rec lexbuf 185
and __ocaml_lex_comment_rec lexbuf __ocaml_lex_state =
  match Lexing.new_engine __ocaml_lex_tables __ocaml_lex_state lexbuf with
      | 0 ->
      ( comment_start_loc := (Location.curr lexbuf) :: !comment_start_loc;
        store_lexeme lexbuf;
        comment lexbuf
      )

  | 1 ->
      ( match !comment_start_loc with
        | [] -> assert false
        | [_] -> comment_start_loc := []; Location.curr lexbuf
        | _ :: l -> comment_start_loc := l;
                  store_lexeme lexbuf;
                  comment lexbuf
       )

  | 2 ->
      (
        string_start_loc := Location.curr lexbuf;
        store_string_char '\"';
        is_in_string := true;
        let _loc = try string lexbuf
        with Error (Unterminated_string, str_start) ->
          match !comment_start_loc with
          | [] -> assert false
          | loc :: _ ->
            let start = List.hd (List.rev !comment_start_loc) in
            comment_start_loc := [];
            error_loc loc (Unterminated_string_in_comment (start, str_start))
        in
        is_in_string := false;
        store_string_char '\"';
        comment lexbuf )

  | 3 ->
let
                                                      raw_delim
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_mem.(0) (lexbuf.Lexing.lex_curr_pos + -1) in
      ( match lax_delim raw_delim with
        | None -> store_lexeme lexbuf; comment lexbuf
        | Some delim ->
        string_start_loc := Location.curr lexbuf;
        store_lexeme lexbuf;
        is_in_string := true;
        let _loc = try quoted_string delim lexbuf
        with Error (Unterminated_string, str_start) ->
          match !comment_start_loc with
          | [] -> assert false
          | loc :: _ ->
            let start = List.hd (List.rev !comment_start_loc) in
            comment_start_loc := [];
            error_loc loc (Unterminated_string_in_comment (start, str_start))
        in
        is_in_string := false;
        store_string_char '|';
        store_string delim;
        store_string_char '}';
        comment lexbuf )

  | 4 ->
      ( store_lexeme lexbuf; comment lexbuf )

  | 5 ->
let
                     nl
= Lexing.sub_lexeme lexbuf (lexbuf.Lexing.lex_start_pos + 1) (lexbuf.Lexing.lex_curr_pos + -1) in
      ( update_loc lexbuf None 1 false 1;
        store_string_char '\'';
        store_normalized_newline nl;
        store_string_char '\'';
        comment lexbuf
      )

  | 6 ->
      ( store_lexeme lexbuf; comment lexbuf )

  | 7 ->
      ( store_lexeme lexbuf; comment lexbuf )

  | 8 ->
      ( store_lexeme lexbuf; comment lexbuf )

  | 9 ->
      ( store_lexeme lexbuf; comment lexbuf )

  | 10 ->
      ( store_lexeme lexbuf; comment lexbuf )

  | 11 ->
      ( match !comment_start_loc with
        | [] -> assert false
        | loc :: _ ->
          let start = List.hd (List.rev !comment_start_loc) in
          comment_start_loc := [];
          error_loc loc (Unterminated_comment start)
      )

  | 12 ->
let
               nl
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_curr_pos in
      ( update_loc lexbuf None 1 false 0;
        store_normalized_newline nl;
        comment lexbuf
      )

