        store_lexeme lexbuf;
        string lexbuf
      )

  | 8 ->
let
               nl
= Lexing.sub_lexeme lexbuf lexbuf.Lexing.lex_start_pos lexbuf.Lexing.lex_curr_pos in
      ( update_loc lexbuf None 1 false 0;
        store_normalized_newline nl;
        string lexbuf
